93	    headingFallback: "Looks like you're {inCountry}",
94	    bodyKey: 'regional.locationPrompt.body',
95	    bodyFallback:
96	      "You're currently shopping on {currentStore}. Switch to {targetStore} for local pricing, currency and shipping options.",
97	    switchCtaKey: 'regional.locationPrompt.cta.switch',
