import { chromium } from 'playwright';
import fs from 'node:fs';

const BASE = 'http://localhost:6006/iframe.html';
const STORIES = [
  { key: 'location', id: 'layout-zimmcountrylanguagemismatch--location' },
  { key: 'language', id: 'layout-zimmcountrylanguagemismatch--language' },
];
const WIDTHS = [375, 402, 768, 1440];
const HEIGHT = 900;
const TRANSITION_BUFFER_MS = 900; // drawer slide transition is 300ms; generous margin added

const results = {};

const browser = await chromium.launch();

for (const story of STORIES) {
  results[story.key] = {};
  for (const width of WIDTHS) {
    let context;
    try {
      context = await browser.newContext({ viewport: { width, height: HEIGHT } });
      const page = await context.newPage();
      const url = `${BASE}?id=${story.id}&viewMode=story`;
      await page.goto(url, { waitUntil: 'load', timeout: 30000 });
      await page.waitForSelector('[role="dialog"]', { timeout: 15000 });
      await page.waitForTimeout(TRANSITION_BUFFER_MS);

      const data = await page.evaluate(() => {
        const rect = (el) => {
          if (!el) return null;
          const r = el.getBoundingClientRect();
          return {
            x: r.x,
            y: r.y,
            width: r.width,
            height: r.height,
            top: r.top,
            left: r.left,
            right: r.right,
            bottom: r.bottom,
          };
        };

        const dialog = document.querySelector('[role="dialog"]');
        const heading = document.querySelector('h2');
        const bodyP = heading ? heading.nextElementSibling : null;
        const contentEl = heading ? heading.parentElement : null;
        const buttonGroupEl = contentEl ? contentEl.nextElementSibling : null;
        const rootEl = contentEl ? contentEl.parentElement : null;
        const buttons = buttonGroupEl ? Array.from(buttonGroupEl.querySelectorAll(':scope > button')) : [];
        const rootCS = rootEl ? getComputedStyle(rootEl) : null;

        return {
          docScrollWidth: document.documentElement.scrollWidth,
          docClientWidth: document.documentElement.clientWidth,
          windowInnerWidth: window.innerWidth,
          bodyScrollWidth: document.body.scrollWidth,
          dialog: rect(dialog),
          heading: heading
            ? {
                ...rect(heading),
                text: heading.textContent,
                scrollWidth: heading.scrollWidth,
                clientWidth: heading.clientWidth,
                scrollHeight: heading.scrollHeight,
                clientHeight: heading.clientHeight,
                overflow: getComputedStyle(heading).overflow,
              }
            : null,
          body: bodyP
            ? {
                ...rect(bodyP),
                text: bodyP.textContent,
                scrollWidth: bodyP.scrollWidth,
                clientWidth: bodyP.clientWidth,
                scrollHeight: bodyP.scrollHeight,
                clientHeight: bodyP.clientHeight,
                overflow: getComputedStyle(bodyP).overflow,
              }
            : null,
          content: rect(contentEl),
          buttonGroup: rect(buttonGroupEl),
          root: rect(rootEl),
          rootPadding: rootCS
            ? {
                top: rootCS.paddingTop,
                right: rootCS.paddingRight,
                bottom: rootCS.paddingBottom,
                left: rootCS.paddingLeft,
              }
            : null,
          buttonCount: buttons.length,
          buttons: buttons.map((b) => ({
            ...rect(b),
            text: b.textContent,
            ariaLabel: b.getAttribute('aria-label'),
          })),
        };
      });

      results[story.key][width] = data;
    } catch (err) {
      results[story.key][width] = { error: String(err && err.stack ? err.stack : err) };
    } finally {
      if (context) await context.close();
    }
  }
}

await browser.close();
fs.writeFileSync('/tmp/clm-results.json', JSON.stringify(results, null, 2));
console.log('DONE');

